import React from "react";

export const getListChildren = (children: React.ReactNode) => {
  const toolbar = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "List.Toolbar",
  );
  const header = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "List.Header",
  );
  const body = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "List.Body",
  );
  const footer = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "List.Footer",
  );

  const filterChipBars = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "List.FilterChipBars",
  );

  const emptyState = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "List.EmptyState",
  );

  return {
    toolbar,
    header,
    body,
    footer,
    filterChipBars,
    emptyState,
  };
};
